CREATE TABLE IF NOT EXISTS content_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_sessions(token TEXT PRIMARY KEY,expires DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS login_limits(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,reset_at DOUBLE PRECISION NOT NULL);
CREATE TABLE IF NOT EXISTS agent_keys(id TEXT PRIMARY KEY,label TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,prefix TEXT NOT NULL,created_at TEXT NOT NULL,last_used_at TEXT,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS agent_requests(key_id TEXT REFERENCES agent_keys(id),request_key TEXT NOT NULL,fingerprint TEXT NOT NULL,response TEXT NOT NULL,status INTEGER NOT NULL,PRIMARY KEY(key_id,request_key));
CREATE TABLE IF NOT EXISTS articles(id TEXT PRIMARY KEY,draft TEXT NOT NULL,published TEXT,status TEXT NOT NULL DEFAULT 'draft',version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS article_revisions(id BIGSERIAL PRIMARY KEY,article_id TEXT NOT NULL REFERENCES articles(id),version INTEGER NOT NULL,payload TEXT NOT NULL,action TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments(id TEXT PRIMARY KEY,article_id TEXT NOT NULL REFERENCES articles(id),name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS upload_sessions(id TEXT PRIMARY KEY,article_id TEXT NOT NULL REFERENCES articles(id),owner TEXT NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL,chunks INTEGER NOT NULL,received TEXT NOT NULL DEFAULT '[]',expires DOUBLE PRECISION NOT NULL,attachment TEXT);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,status TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT);
CREATE TABLE IF NOT EXISTS resident_profiles(id TEXT PRIMARY KEY,session_id TEXT REFERENCES sessions(id),status TEXT NOT NULL CHECK(status IN ('draft','joined')),display_name TEXT NOT NULL DEFAULT '',role TEXT NOT NULL,appearance_json TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,date TEXT NOT NULL,status TEXT NOT NULL,questions TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),profile_id TEXT NOT NULL REFERENCES resident_profiles(id),token TEXT NOT NULL UNIQUE,progress INTEGER NOT NULL DEFAULT 0,attempts INTEGER NOT NULL DEFAULT 0,completed_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS player_positions(profile_id TEXT PRIMARY KEY REFERENCES resident_profiles(id),x DOUBLE PRECISION NOT NULL,z DOUBLE PRECISION NOT NULL,heading DOUBLE PRECISION NOT NULL DEFAULT 0,sequence DOUBLE PRECISION NOT NULL DEFAULT 0,updated_at DOUBLE PRECISION NOT NULL,input_dx DOUBLE PRECISION NOT NULL DEFAULT 0,input_dz DOUBLE PRECISION NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS wishes(id TEXT PRIMARY KEY,owner TEXT NOT NULL,text TEXT NOT NULL,island INTEGER NOT NULL CHECK(island BETWEEN 0 AND 9),status TEXT NOT NULL CHECK(status IN ('lit','completed','archived')),created_at TEXT NOT NULL,completed_at TEXT);
CREATE INDEX IF NOT EXISTS participants_event ON participants(event_id);
CREATE INDEX IF NOT EXISTS positions_updated ON player_positions(updated_at);
CREATE INDEX IF NOT EXISTS wishes_owner ON wishes(owner);
